package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"
)

func main() {
	if len(os.Args) < 3 {
		fmt.Println("Usage: go run parser.go [GoSourceFile] [StructName]")
		return
	}

	gofilename := os.Args[1]
	structname := os.Args[2]

	file, err := os.Open(gofilename)
	if err != nil {
		log.Fatalf("failed to open %s: %v", gofilename, err)
	}
	defer file.Close()

	var astFile *parse.File
	astFile, err = parser.ParseFile(token.NewFileSet(), "", file, 0)
	if err != nil {
		log.Fatalf("failed to parse %s: %v", gofilename, err)
	}

	if astFile == nil || astFile.List == nil {
		log.Fatalf("No structs found in %s", gofilename)
	}

	schema := make(map[string]*schema.Field)

	for _, decl := range astFile.List.Decls {
		switch t := decl.(*ast.GenDecl).Kind; t {
		case token.TYPE:
			if strings.HasPrefix(t.Name.Value, "struct") {
				fieldType := ""
				for _, arg := range decl.Arguments.List {
					if arg.Type.Kind() == token.STRING {
						fieldType = arg.Type.String()
					} else if arg.Type.Kind() == token.NAME && arg.Type.String() == "int8" {
						continue // Skip int8 field
					}
				}

				name := fmt.Sprintf("%s.%s", structname, decl.Names[0].Ident.Value)
				schema[name] = &schema.Field{
					Name:     name,
					Type:     fieldType,
					Optional: true,
				}
			}
		}
	}

	if len(schema) == 0 {
		log.Fatalf("No fields found in %s", gofilename)
	}

	content := fmt.Sprintf(`# Licensed under Apache-2.0 License.
// Code generated by parsing Go file, DO NOT EDIT.
package mypackage

%+s

%s

// GeneratedAvroSchema is the Avro schema for the struct defined in %s.go.
type GeneratedAvroSchema struct {
%+v
}`,

	"", // Placeholder for comments
	schema)

	outfile, err := ioutil.TempFile("", "generated_schema")
	if err != nil {
		log.Fatalf("Failed to create temporary file: %v", err)
	}
	defer outfile.Close()

	err = ioutil.WriteFile(outfile.Name(), []byte(content), 0644)
	if err != nil {
		log.Fatalf("Failed to write to temporary file: %v", err)
	}

	fmt.Printf("Generated Avro schema saved to %s\n", outfile.Name())
}
```

